/**
 * FORGE — AI Output Firewall
 *
 * Nothing generated by an external model is trusted until it passes this layer.
 * This is intentionally deterministic: no second AI is used to decide whether
 * another AI's output is sane.
 */

const SPECIAL_TOKEN = /<\|[^>]{0,120}\|>/;
const CODE_FENCE = /```/;
const CONTROL = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/;
const ASSISTANT_LEAK = /\b(?:as an ai|as an assistant|i cannot|i can't|here(?:'|’)s|sure[,!]|certainly[,!]|apologies|sorry[,!]|i will provide|let me explain)\b/i;
const META_LEAK = /\b(?:system prompt|developer message|internal reasoning|chain of thought|hidden instruction|tool call|function call)\b/i;

function fail(code, message, details = {}) {
  const err = new Error(`FORGE_OUTPUT_FIREWALL:${code}: ${message}`);
  err.code = code;
  err.details = details;
  err.retryable = true;
  return err;
}

function repetitionScore(text) {
  const s = String(text || '').replace(/\s+/g, ' ').trim();
  if (s.length < 120) return 0;
  const words = s.split(' ');
  if (words.length < 30) return 0;
  let repeatedRuns = 0;
  for (let i = 0; i < words.length - 5; i++) {
    const phrase = words.slice(i, i + 5).join(' ').toLowerCase();
    let hits = 1;
    for (let j = i + 5; j + 4 < words.length; j += 5) {
      if (words.slice(j, j + 5).join(' ').toLowerCase() === phrase) hits++;
    }
    if (hits >= 3) repeatedRuns = Math.max(repeatedRuns, hits);
  }
  return repeatedRuns;
}


function sceneCodeRepetitionScore(text) {
  const lines = String(text || '')
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(line => line.length >= 28);
  if (lines.length < 30) return 0;

  const counts = new Map();
  for (const line of lines) counts.set(line, (counts.get(line) || 0) + 1);
  let maxSameLine = 0;
  for (const count of counts.values()) maxSameLine = Math.max(maxSameLine, count);

  // A repeated executable line is normal in loops, so only flag extreme
  // repetition. This targets model garbage without rejecting legitimate code.
  if (maxSameLine >= 9) return maxSameLine;

  const normalized = lines.map(line => line.replace(/\s+/g, ' '));
  for (let size = 3; size <= 6; size++) {
    for (let i = 0; i + size * 3 <= normalized.length; i++) {
      const block = normalized.slice(i, i + size).join('\n');
      let hits = 1;
      for (let j = i + size; j + size <= normalized.length; j += size) {
        if (normalized.slice(j, j + size).join('\n') === block) hits++;
      }
      if (hits >= 3) return hits;
    }
  }
  return 0;
}

function walkStrings(value, visit, path = '$') {
  if (typeof value === 'string') {
    visit(value, path);
    return;
  }
  if (Array.isArray(value)) {
    value.forEach((v, i) => walkStrings(v, visit, `${path}[${i}]`));
    return;
  }
  if (value && typeof value === 'object') {
    for (const [key, v] of Object.entries(value)) {
      walkStrings(v, visit, `${path}.${key}`);
    }
  }
}

export function guardRawModelText(rawText, mode) {
  const raw = String(rawText ?? '').trim();
  if (!raw) throw fail('EMPTY_OUTPUT', 'Model returned empty output.');
  if (raw.length > 2_000_000) throw fail('OUTPUT_TOO_LARGE', 'Model output exceeded the hard safety ceiling.');
  if (SPECIAL_TOKEN.test(raw)) throw fail('SPECIAL_TOKEN_GARBAGE', 'Model emitted an internal/special token.');
  if (CODE_FENCE.test(raw)) throw fail('MARKDOWN_LEAK', 'Markdown/code-fence leakage is not allowed in structured output.');
  if (CONTROL.test(raw)) throw fail('CONTROL_CHARACTER', 'Model emitted unsupported control characters.');

  // Outside the JSON contract, assistant/meta chatter is always a failure.
  if (ASSISTANT_LEAK.test(raw) || META_LEAK.test(raw)) {
    throw fail('AI_CHATTER_LEAK', 'Model emitted assistant/meta chatter instead of the FORGE contract.');
  }

  const score = mode === 'scene_code' ? 0 : repetitionScore(raw);
  if (score >= 3) throw fail('REPETITIVE_GARBAGE', 'Model output contains a degenerate repeated phrase pattern.');

  // Every structured FORGE response must be exactly one JSON object. We do not
  // silently salvage prefixes/suffixes because doing so can hide brain-fart text.
  if (!raw.startsWith('{') || !raw.endsWith('}')) {
    throw fail('NON_OBJECT_OUTPUT', `${mode} output is not exactly one JSON object.`);
  }
}

export function guardParsedOutput(result, mode) {
  if (!result || typeof result !== 'object' || Array.isArray(result)) {
    throw fail('NOT_OBJECT', `${mode} parsed output is not a JSON object.`);
  }

  let stringCount = 0;
  walkStrings(result, (value, path) => {
    stringCount++;
    if (SPECIAL_TOKEN.test(value)) throw fail('SPECIAL_TOKEN_GARBAGE', `Special token found at ${path}.`);
    if (CONTROL.test(value)) throw fail('CONTROL_CHARACTER', `Control character found at ${path}.`);
    if (value.includes('```')) throw fail('MARKDOWN_LEAK', `Code fence found at ${path}.`);
    const isSceneCode = mode === 'scene_code' && path === '$.code';
    const repeated = isSceneCode ? sceneCodeRepetitionScore(value) : repetitionScore(value);
    if (repeated >= 3) throw fail('REPETITIVE_GARBAGE', `Repeated phrase pattern found at ${path}.`);
  });

  if (stringCount === 0 && mode !== 'validate') {
    throw fail('NO_TEXT_FIELDS', `${mode} output contains no string content.`);
  }

  return result;
}

export function guardSceneCode(code) {
  const text = String(code || '').trim();
  if (!text) throw fail('EMPTY_SCENE_CODE', 'Scene code is empty.');
  if (text.length < 100) throw fail('SHORT_SCENE_CODE', 'Scene code is implausibly short.');
  if (text.length > 180_000) throw fail('HUGE_SCENE_CODE', 'Scene code exceeds the hard safety ceiling.');
  if (SPECIAL_TOKEN.test(text)) throw fail('SPECIAL_TOKEN_GARBAGE', 'Scene code contains an internal model token.');
  if (CODE_FENCE.test(text)) throw fail('MARKDOWN_LEAK', 'Scene code contains Markdown fences.');
  if (CONTROL.test(text)) throw fail('CONTROL_CHARACTER', 'Scene code contains unsupported control characters.');

  // Common model-failure signatures. These are forbidden in executable scene code.
  if (/^\s*(?:here(?:'|’)s|sure|certainly|okay|ok)[,!:]/i.test(text)) {
    throw fail('CODE_CHATTER_LEAK', 'Scene code starts with conversational model chatter.');
  }
  if (/^\s*(?:javascript|js|jsx|typescript|tsx)\s*[:\-]/i.test(text)) {
    throw fail('LANGUAGE_LABEL_LEAK', 'Scene code contains a language label instead of source code.');
  }
  if (/\b(?:system prompt|internal reasoning|chain of thought|tool call)\b/i.test(text)) {
    throw fail('META_TEXT_IN_CODE', 'Scene code contains model-internal/meta text.');
  }

  return text;
}

export const __test = { repetitionScore, sceneCodeRepetitionScore };
